  quoteId?: string | null;
  /**
     * Instante do fechamento (ganho ou perda). Escrito pelo SERVIDOR quando a oportunidade entra num estágio `isWon`/`isLost`, e limpo quando ela volta a um estágio aberto.
     * @nullable
     */
  closedAt?: string | null;
