  /**
     * Fornecedor da linha (`PartnerDto.id`).
     * @nullable
     */
  supplierId?: string | null;
  /** @nullable */
  supplierName?: string | null;
  /**
     * Código do produto NO fornecedor — a língua em que o item é pedido.
     * @nullable
     */
